import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_positions = inputs["target_positions"].copy()
    position_events = inputs["position_events"].copy()

    # Ensure proper types
    target_positions = target_positions.astype({
        'account_id': 'int64',
        'symbol': 'str',
        'qty': 'int64',
        'price': 'float64',
        'row_version': 'int64'
    })

    position_events = position_events.astype({
        'batch_seq': 'int64',
        'account_id': 'int64',
        'symbol': 'str',
        'op': 'str',
        'qty': 'float64',
        'price': 'float64',
        'row_version': 'int64'
    })

    # Step 1: Remove duplicate deliveries (keep first occurrence by batch_seq per composite key)
    position_events = position_events.drop_duplicates(
        subset=['account_id', 'symbol', 'batch_seq'],
        keep='first'
    ).reset_index(drop=True)

    # Create a working copy of target_positions indexed by (account_id, symbol)
    state = target_positions.set_index(['account_id', 'symbol']).to_dict('index')

    # Track closed positions: key -> closed_version
    closed_positions_dict = {}

    # Step 2: Apply events in order of row_version, then batch_seq
    position_events = position_events.sort_values(['row_version', 'batch_seq']).reset_index(drop=True)

    for _, event in position_events.iterrows():
        account_id = int(event['account_id'])
        symbol = str(event['symbol'])
        op = str(event['op'])
        event_qty = event['qty']
        event_price = event['price']
        event_row_version = int(event['row_version'])
        key = (account_id, symbol)

        # Step 2a: Replay guard - skip if key exists and event version <= existing version
        if key in state:
            existing_version = state[key]['row_version']
            if event_row_version <= existing_version:
                continue

        # Step 2b: Apply the event
        if op == 'D':
            # Delete: remove row if exists
            if key in state:
                closed_positions_dict[key] = event_row_version
                del state[key]
        elif op in ('I', 'U'):
            # Check if qty == 0 (close the position)
            if pd.isna(event_qty) or event_qty == 0:
                # Close: same as delete
                if key in state:
                    closed_positions_dict[key] = event_row_version
                    del state[key]
            else:
                # Insert or update with non-zero qty
                if key in state:
                    # Update existing row
                    state[key]['qty'] = int(event_qty)
                    # For 'U' with NULL price, keep existing price
                    if op == 'U' and pd.isna(event_price):
                        pass  # keep existing price
                    else:
                        state[key]['price'] = event_price
                    state[key]['row_version'] = event_row_version
                else:
                    # Create new row
                    state[key] = {
                        'account_id': account_id,
                        'symbol': symbol,
                        'qty': int(event_qty),
                        'price': event_price,
                        'row_version': event_row_version
                    }

    # Step 3: Build new_positions from state
    if state:
        new_positions_list = list(state.values())
        new_positions = pd.DataFrame(new_positions_list)
        new_positions = new_positions[['account_id', 'symbol', 'qty', 'price', 'row_version']]
    else:
        new_positions = pd.DataFrame(columns=['account_id', 'symbol', 'qty', 'price', 'row_version'])

    # Ensure correct dtypes for new_positions
    new_positions = new_positions.astype({
        'account_id': 'int64',
        'symbol': 'str',
        'qty': 'int64',
        'price': 'float64',
        'row_version': 'int64'
    })

    # Step 4: Build closed_positions
    if closed_positions_dict:
        closed_list = [
            {'account_id': k[0], 'symbol': k[1], 'closed_version': v}
            for k, v in closed_positions_dict.items()
        ]
        closed_positions = pd.DataFrame(closed_list)
    else:
        closed_positions = pd.DataFrame(columns=['account_id', 'symbol', 'closed_version'])

    closed_positions = closed_positions.astype({
        'account_id': 'int64',
        'symbol': 'str',
        'closed_version': 'int64'
    })

    return {
        'new_positions': new_positions,
        'closed_positions': closed_positions
    }
